/*
	VIOC_weapon_workshop.sqf - agregado por tools/vio_build.py (parche weapon_workshop; copia configurada, no es del autor
	de la mision). Generado desde work/vio_workshop/ (make_patch.py).

	"TALLER: Accesorios de armas" (como en Arma Reforger): abre el Arsenal de BI con la vista 3D de tu soldado y su
	arma, limitado a las armas que ya llevas (no se pueden cambiar) y a los accesorios que vende la tienda de tu bando
	(respeta el nivel de mejora Gear, igual que el menu de equipo). Las pestanas de mira, boca, lateral y bipode del
	Arsenal solo muestran lo que le queda al arma elegida.

	Al cerrar el Arsenal (evento "arsenalClosed"):
	  - Se vuelve EXACTAMENTE al equipo que tenias al abrir (ropa, chaleco, mochila, cargadores, objetos, etc.); solo
	    se aplican los accesorios de las tres armas (boca, lateral, mira, bipode). Asi "Aleatorio", "Cargar", "<Vacio>"
	    o Ctrl+Shift+R del Arsenal no pueden cambiar nada mas ni regalar objetos.
	  - Cada accesorio nuevo se valida: tiene que ser compatible con esa arma y salir (en este orden) de un accesorio que
	    quitaste en esta misma visita, de tu inventario (se saca de ahi, gratis) o de la tienda (se cobra su precio).
	    Si no, ese hueco queda como estaba.
	  - Si no te alcanza el dinero para el total, se deshace todo y un aviso te dice cuanto cuesta.
	  - Los accesorios que quitas y no vuelves a montar van a tu inventario si caben; si no, se pierden (te avisa).
	  - Las miras con version PIP de CBA (p. ej. las PSO de CUP) se comparan por su clase normal: no se cobran dos veces.
	Si mueres dentro del Arsenal, el cuerpo vuelve a los accesorios de antes y el equipo de reaparicion
	("Start with last Gear") es el de antes de entrar.

	Tambien da la lista filtrada de la pestana de accesorios del menu de equipo (VIOC_WS_fnc_gearAccList): solo los
	accesorios compatibles con las armas de la unidad que editas, agrupados (mira, boca, lateral, bipode) y por nombre.

	Solo cliente (hasInterface). Parametro de lobby VIOC_WEAPON_WORKSHOP (0 = No, 1 = Si). Nada se crea en el mapa:
	la lista del Arsenal va en una variable local del propio jugador y se borra al cerrar.
*/
if (!hasInterface) exitWith {};
if ((missionNamespace getVariable ["VIOC_WEAPON_WORKSHOP", 1]) < 1) exitWith {};

//--- Huecos de accesorio en el arreglo de arma de getUnitLoadout: [indice, nombre de ranura de CTI_CL_FNC_GetCompatibleItems, ItemInfo type]
VIOC_WS_SLOTS = [[1, "muzzle", 101], [2, "pointer", 301], [3, "optic", 201], [6, "bipod", 302]];
VIOC_WS_COMPAT_CACHE = [];

//--- Clase "normal" en minusculas (CBA optics cambia algunas miras a su version PIP fuera del Arsenal).
VIOC_WS_fnc_norm = {
	private _c = _this;
	if !(_c isEqualType "") exitWith {""};
	if (_c == "") exitWith {""};
	{
		private _ns = missionNamespace getVariable _x;
		if (!isNil "_ns" && {_ns isEqualType locationNull || {_ns isEqualType objNull}} && {!isNull _ns}) then {
			private _n = _ns getVariable [_c, ""];
			if (_n isEqualType "" && {_n != ""}) then {_c = _n};
		};
	} forEach ["cba_optics_NonPIPOptics", "cba_optics_NonCarryHandleOptics"];
	toLower _c
};

//--- Accesorios compatibles con un arma, por ranura: [boca, lateral, mira, bipode] (minusculas, sin repetir).
//--- Une la lista de la mision (CTI_CL_FNC_GetCompatibleItems) y la de BIS (la que usa el Arsenal), por tipo de objeto.
VIOC_WS_fnc_compatSlots = {
	params [["_weapon", "", [""]]];
	if (_weapon == "" || {!isClass (configFile >> "CfgWeapons" >> _weapon)}) exitWith {[[], [], [], []]};
	private _i = VIOC_WS_COMPAT_CACHE findIf {(_x select 0) == _weapon};
	if (_i >= 0) exitWith {(VIOC_WS_COMPAT_CACHE select _i) select 1};
	private _all = [];
	if (!isNil "CTI_CL_FNC_GetCompatibleItems") then {
		{
			private _l = [_weapon, _x select 1] call CTI_CL_FNC_GetCompatibleItems;
			if (!isNil "_l" && {_l isEqualType []}) then {_all append _l};
		} forEach VIOC_WS_SLOTS;
	};
	_all append ([_weapon] call BIS_fnc_compatibleItems);
	private _out = [[], [], [], []];
	private _types = VIOC_WS_SLOTS apply {_x select 2};
	{
		if (_x isEqualType "" && {isClass (configFile >> "CfgWeapons" >> _x)}) then {
			private _s = _types find (getNumber (configFile >> "CfgWeapons" >> _x >> "ItemInfo" >> "type"));
			if (_s >= 0) then {(_out select _s) pushBackUnique (toLower _x)};
		};
	} forEach _all;
	VIOC_WS_COMPAT_CACHE pushBack [_weapon, _out];
	_out
};

//--- Nivel de mejora Gear del bando del jugador (como el menu de equipo).
VIOC_WS_fnc_gearLevel = {
	if (isNil "CTI_CO_FNC_GetSideUpgrades" || {isNil "CTI_UPGRADE_GEAR"}) exitWith {0};
	private _ups = (CTI_P_SideJoined) call CTI_CO_FNC_GetSideUpgrades;
	if (isNil "_ups" || {!(_ups isEqualType [])}) exitWith {0};
	private _l = _ups param [CTI_UPGRADE_GEAR, 0];
	if !(_l isEqualType 0) exitWith {0};
	_l
};

//--- Precio de tienda de un accesorio (clase en minusculas) o -1 si tu tienda no lo vende a este nivel.
VIOC_WS_fnc_shopPrice = {
	params ["_item", "_level"];
	if !(_item in (missionNamespace getVariable ["cti_gear_list_accessories", []])) exitWith {-1};
	private _get = missionNamespace getVariable _item;
	if (isNil "_get" || {!(_get isEqualType [])} || {count _get < 1} || {!((_get select 0) isEqualType [])}) exitWith {-1};
	private _lp = _get select 0;
	if (((_lp param [0, 0]) > _level)) exitWith {-1};
	_lp param [1, 0]
};

//--- Objetos sueltos (no cargadores ni armas) de uniforme, chaleco y mochila de un getUnitLoadout: [[normal, clase], ...] uno por unidad.
VIOC_WS_fnc_invItems = {
	params ["_lo"];
	private _out = [];
	{
		private _c = _lo param [_x, []];
		if (_c isEqualType [] && {count _c > 1} && {(_c select 1) isEqualType []}) then {
			{
				if (_x isEqualType [] && {count _x == 2} && {(_x select 0) isEqualType ""} && {(_x select 1) isEqualType 0}) then {
					private _pair = [(_x select 0) call VIOC_WS_fnc_norm, _x select 0];
					for "_i" from 1 to ((_x select 1) min 50) do {_out pushBack _pair};
				};
			} forEach (_c select 1);
		};
	} forEach [3, 4, 5];
	_out
};

//--- Compara el equipo de antes (_snap) con el del Arsenal (_now). Devuelve
//--- [equipo final, costo, compras [[clase, precio]], quitados sin usar [[normal, clase]], sacados del inventario [clase], rechazados [clase]].
//--- El equipo final es _snap con solo los accesorios de las armas cambiados.
VIOC_WS_fnc_evaluate = {
	params ["_snap", "_now", "_level"];
	private _final = +_snap;
	private _pool = [];
	private _wants = [];
	{
		private _w = _x;
		private _sw = _snap param [_w, []];
		private _rw = _now param [_w, []];
		if (_sw isEqualType [] && {count _sw > 6} && {_rw isEqualType []} && {count _rw > 6} && {(_sw select 0) isEqualType ""} && {(_rw select 0) isEqualType ""} && {(_sw select 0) != ""} && {(_rw select 0) != ""}) then {
			//--- Misma arma (el Arsenal solo ofrece las tuyas; si la quitaste o cambiaste, ese arma no se toca)
			if ((((_sw select 0) call VIOC_WS_fnc_norm) call BIS_fnc_baseWeapon) == (((_rw select 0) call VIOC_WS_fnc_norm) call BIS_fnc_baseWeapon)) then {
				{
					private _k = _x select 0;
					private _old = _sw select _k;
					private _new = _rw select _k;
					if (_old isEqualType "" && {_new isEqualType ""}) then {
						private _nOld = _old call VIOC_WS_fnc_norm;
						private _nNew = _new call VIOC_WS_fnc_norm;
						if (_nOld != _nNew) then {
							if (_nOld != "") then {_pool pushBack [_nOld, _old]};
							if (_nNew != "") then {
								_wants pushBack [_w, _k, _forEachIndex, _new, _nNew];
							} else {
								(_final select _w) set [_k, ""];
							};
						};
					};
				} forEach VIOC_WS_SLOTS;
			};
		};
	} forEach [0, 1, 2];

	private _inv = [_snap] call VIOC_WS_fnc_invItems;
	private _cost = 0;
	private _buys = [];
	private _fromInv = [];
	private _rejected = [];
	{
		_x params ["_w", "_k", "_s", "_new", "_nNew"];
		private _old = (_final select _w) select _k;
		private _ok = false;
		private _compat = ([((_snap select _w) select 0) call VIOC_WS_fnc_norm] call VIOC_WS_fnc_compatSlots) select _s;
		if (_nNew in _compat || {(toLower _new) in _compat}) then {
			private _i = _pool findIf {(_x select 0) == _nNew};
			if (_i >= 0) then {
				_pool deleteAt _i;
				_ok = true;
			} else {
				_i = _inv findIf {(_x select 0) == _nNew};
				if (_i >= 0) then {
					_fromInv pushBack ((_inv deleteAt _i) select 1);
					_ok = true;
				} else {
					private _price = round ([_nNew, _level] call VIOC_WS_fnc_shopPrice);
					if (_price >= 0) then {
						_cost = _cost + _price;
						_buys pushBack [_new, _price];
						_ok = true;
					};
				};
			};
		};
		if (_ok) then {
			(_final select _w) set [_k, _new];
		} else {
			_rejected pushBack _new;
			//--- Vuelve el de antes si sigue libre; si otra arma ya lo tomo, el hueco queda vacio (nada se duplica)
			if (_old != "") then {
				private _j = _pool findIf {(_x select 0) == (_old call VIOC_WS_fnc_norm)};
				if (_j >= 0) then {_pool deleteAt _j} else {(_final select _w) set [_k, ""]};
			};
		};
	} forEach _wants;
	[_final, _cost, _buys, _pool, _fromInv, _rejected]
};

//--- Deja los accesorios montados exactamente como en _final (setUnitLoadout puede volver a poner los de fabrica).
VIOC_WS_fnc_fixAttachments = {
	params ["_unit", "_final"];
	{
		private _w = _x;
		private _fw = _final param [_w, []];
		private _cur = [primaryWeapon _unit, secondaryWeapon _unit, handgunWeapon _unit] select _w;
		if (_fw isEqualType [] && {count _fw > 6} && {(_fw select 0) isEqualType ""} && {(_fw select 0) != ""} && {_cur != ""}
			&& {((_cur call VIOC_WS_fnc_norm) call BIS_fnc_baseWeapon) == (((_fw select 0) call VIOC_WS_fnc_norm) call BIS_fnc_baseWeapon)}) then {
			private _have = switch (_w) do {case 0: {primaryWeaponItems _unit}; case 1: {secondaryWeaponItems _unit}; default {handgunItems _unit}};
			{
				private _want = _x;
				private _h = _have param [_forEachIndex, ""];
				if ((_h call VIOC_WS_fnc_norm) != (_want call VIOC_WS_fnc_norm)) then {
					if (_h != "") then {
						switch (_w) do {case 0: {_unit removePrimaryWeaponItem _h}; case 1: {_unit removeSecondaryWeaponItem _h}; default {_unit removeHandgunItem _h}};
					};
					if (_want != "") then {
						switch (_w) do {case 0: {_unit addPrimaryWeaponItem _want}; case 1: {_unit addSecondaryWeaponItem _want}; default {_unit addHandgunItem _want}};
					};
				};
			} forEach [_fw select 1, _fw select 2, _fw select 3, _fw select 6];
		};
	} forEach [0, 1, 2];
};

VIOC_WS_fnc_selectWeapon = {
	params ["_unit", "_cw"];
	if (_cw != "" && {currentWeapon _unit != _cw} && {_cw in [primaryWeapon _unit, secondaryWeapon _unit, handgunWeapon _unit]}) then {_unit selectWeapon _cw};
};

//--- Nombres para mostrar ("Nombre ($precio)" si se pasa [clase, precio]).
VIOC_WS_fnc_names = {
	(_this apply {
		private _c = if (_x isEqualType []) then {_x select 0} else {_x};
		private _d = getText (configFile >> "CfgWeapons" >> _c >> "displayName");
		if (_d == "") then {_d = _c};
		if (_x isEqualType [] && {count _x > 1} && {(_x select 1) isEqualType 0}) then {format ["%1 ($%2)", _d, _x select 1]} else {_d}
	}) joinString ", "
};

//--- Escapa texto para parseText.
VIOC_WS_fnc_esc = {
	private _s = _this;
	{_s = (_s splitString (_x select 0)) joinString (_x select 1)} forEach [["&", "&amp;"], ["<", "&lt;"], [">", "&gt;"]];
	_s
};

//--- Mismo lugar que permite el menu de equipo (cuartel, camion de municion, FOB, campamento o deposito de pueblo).
VIOC_WS_fnc_inRange = {
	!(missionNamespace getVariable ["CTI_P_PreBuilding", false]) && {
		(missionNamespace getVariable ["CTI_Base_GearInRange", false]) || {missionNamespace getVariable ["CTI_Base_GearInRange_Mobile", false]}
		|| {missionNamespace getVariable ["CTI_Base_GearInRange_FOB", false]} || {missionNamespace getVariable ["CTI_Town_GearInRange", false]}
	}
};

//--- El Arsenal sigue abierto (su pantalla registrada o su camara)
VIOC_WS_fnc_arsenalUp = {
	!isNull (uiNamespace getVariable ["RscDisplayArsenal", displayNull]) || {!isNull (uiNamespace getVariable ["BIS_fnc_arsenal_cam", objNull])}
};

VIOC_WS_fnc_cleanup = {
	if (!isNil "VIOC_WS_EH_OPENED") then {[missionNamespace, "arsenalOpened", VIOC_WS_EH_OPENED] call BIS_fnc_removeScriptedEventHandler};
	if (!isNil "VIOC_WS_EH_CLOSED") then {[missionNamespace, "arsenalClosed", VIOC_WS_EH_CLOSED] call BIS_fnc_removeScriptedEventHandler};
	if (!isNil "VIOC_WS_UNIT" && {!isNull VIOC_WS_UNIT}) then {
		VIOC_WS_UNIT setVariable ["bis_addVirtualWeaponCargo_cargo", nil];
		if (missionNamespace getVariable ["VIOC_WS_GOD", false]) then {VIOC_WS_UNIT allowDamage true};
	};
	VIOC_WS_EH_OPENED = nil;
	VIOC_WS_EH_CLOSED = nil;
	VIOC_WS_UNIT = nil;
	VIOC_WS_SNAP = nil;
	VIOC_WS_EQUIP = nil;
	VIOC_WS_CURWPN = nil;
	VIOC_WS_LEVEL = nil;
	VIOC_WS_OPENED = nil;
	VIOC_WS_CANCEL = nil;
	VIOC_WS_GOD = nil;
	VIOC_WS_T0 = nil;
	VIOC_WS_SESSION = nil;
};

VIOC_WS_fnc_abort = {
	call VIOC_WS_fnc_cleanup;
	if (_this != "") then {hint _this};
};

//--- Accion "TALLER: Accesorios de armas" (y boton del menu de equipo). Se ejecuta con spawn.
VIOC_WS_fnc_open = {
	if (!hasInterface) exitWith {};
	//--- Una sola visita a la vez (comprobar y marcar sin interrupciones)
	private _busy = true;
	isNil {
		if (!isNil "VIOC_WS_SESSION" && {!(call VIOC_WS_fnc_arsenalUp)} && {diag_tickTime - (missionNamespace getVariable ["VIOC_WS_T0", 0]) > 30}) then {call VIOC_WS_fnc_cleanup}; //--- visita colgada
		if (isNil "VIOC_WS_SESSION") then {VIOC_WS_SESSION = diag_tickTime; VIOC_WS_T0 = diag_tickTime; _busy = false};
	};
	if (_busy) exitWith {};
	private _token = VIOC_WS_SESSION;

	//--- Si se abrio desde el menu de equipo, esperar a que se cierre
	private _t = diag_tickTime + 3;
	waitUntil {!dialog || {diag_tickTime > _t}};
	if (dialog) then {closeDialog 0};
	//--- KJW Two Primary Weapons cambia de fusil ~1.4 s despues de la tecla: no tomar la foto del equipo a mitad del cambio
	if (!isNil "KJW_TwoPrimaryWeapons_fnc_switchPrimaryHandler" && {currentWeapon player == ""} && {primaryWeapon player != ""}) then {uiSleep 2};

	private _unit = player;
	if (isNull _unit || {!alive _unit}) exitWith {"" call VIOC_WS_fnc_abort};
	if (vehicle _unit != _unit) exitWith {"Taller de armas: bajate del vehiculo para usarlo." call VIOC_WS_fnc_abort};
	if !(call VIOC_WS_fnc_inRange) exitWith {"Taller de armas: acercate a un lugar donde se compre equipo (cuartel, camion de municion, FOB o campamento)." call VIOC_WS_fnc_abort};
	if (isNil "CTI_CL_FNC_GetPlayerFunds" || {isNil "CTI_CL_FNC_ChangePlayerFunds"} || {isNil "BIS_fnc_arsenal"}) exitWith {"Taller de armas: la mision todavia esta cargando, prueba en unos segundos." call VIOC_WS_fnc_abort};
	if (call VIOC_WS_fnc_arsenalUp) exitWith {"Taller de armas: ya hay un arsenal abierto." call VIOC_WS_fnc_abort};
	private _weapons = [primaryWeapon _unit, secondaryWeapon _unit, handgunWeapon _unit] select {_x != ""};
	if (_weapons isEqualTo []) exitWith {"Taller de armas: no llevas ningun arma. Compra una en MENU: Equipment." call VIOC_WS_fnc_abort};

	//--- Lista blanca: accesorios de tu tienda (a tu nivel de Gear) que le quedan a alguna de tus armas
	private _level = call VIOC_WS_fnc_gearLevel;
	private _compat = [];
	{
		{_compat append _x} forEach ([_x call VIOC_WS_fnc_norm] call VIOC_WS_fnc_compatSlots);
	} forEach _weapons;
	_compat = _compat arrayIntersect _compat;
	private _shop = (missionNamespace getVariable ["cti_gear_list_accessories", []]) select {(_x in _compat) && {([_x, _level] call VIOC_WS_fnc_shopPrice) >= 0}};

	VIOC_WS_UNIT = _unit;
	VIOC_WS_SNAP = getUnitLoadout _unit;
	VIOC_WS_LEVEL = _level;
	VIOC_WS_EQUIP = if (isNil "CTI_UI_Gear_GetUnitEquipment") then {[]} else {_unit call CTI_UI_Gear_GetUnitEquipment};
	VIOC_WS_CURWPN = currentWeapon _unit;
	VIOC_WS_OPENED = false;
	VIOC_WS_CANCEL = false;
	//--- Invulnerable solo mientras esta en el taller (no ve nada a su alrededor y asi el cuerpo no puede quedar con el equipo del Arsenal)
	VIOC_WS_GOD = isDamageAllowed _unit;
	if (VIOC_WS_GOD) then {_unit allowDamage false};

	//--- Carga virtual local del propio jugador (no se comparte con otras maquinas y no deja objetos en el mapa)
	_unit setVariable ["bis_addVirtualWeaponCargo_cargo", nil];
	[_unit, _shop, false, false] call BIS_fnc_addVirtualItemCargo;
	[_unit, _weapons apply {(_x call VIOC_WS_fnc_norm) call BIS_fnc_baseWeapon}, false, false] call BIS_fnc_addVirtualWeaponCargo;

	VIOC_WS_EH_OPENED = [missionNamespace, "arsenalOpened", {_this call VIOC_WS_fnc_onOpened}] call BIS_fnc_addScriptedEventHandler;
	VIOC_WS_EH_CLOSED = [missionNamespace, "arsenalClosed", {_this call VIOC_WS_fnc_onClosed}] call BIS_fnc_addScriptedEventHandler;

	hintSilent "Taller de armas: abriendo el arsenal (la primera vez en la partida tarda unos segundos)...";
	["Open", [false, _unit, _unit]] call BIS_fnc_arsenal;

	//--- Guardia: si el Arsenal no llego a abrirse, o se cerro sin que llegara "arsenalClosed" (error en otro script),
	//--- se vuelve al equipo de antes y se quita la invulnerabilidad. Nunca mientras su pantalla siga abierta, y nunca
	//--- sobre una visita mas nueva (_token).
	private _fnc_guard = {
		params ["_unit", "_token", "_msg"];
		isNil {
			if ((missionNamespace getVariable ["VIOC_WS_SESSION", -1]) isEqualTo _token && {!(call VIOC_WS_fnc_arsenalUp)}) then {
				if (alive _unit && {!isNil "VIOC_WS_SNAP"} && {!((getUnitLoadout _unit) isEqualTo VIOC_WS_SNAP)}) then {_unit setUnitLoadout VIOC_WS_SNAP};
				_msg call VIOC_WS_fnc_abort;
			};
		};
	};
	private _t0 = diag_tickTime;
	waitUntil {uiSleep 0.5; !((missionNamespace getVariable ["VIOC_WS_SESSION", -1]) isEqualTo _token) || {missionNamespace getVariable ["VIOC_WS_OPENED", false]} || {diag_tickTime - _t0 > 90}};
	if !(missionNamespace getVariable ["VIOC_WS_OPENED", false]) then {[_unit, _token, "Taller de armas: no se pudo abrir el arsenal."] call _fnc_guard};
	waitUntil {uiSleep 1; !((missionNamespace getVariable ["VIOC_WS_SESSION", -1]) isEqualTo _token) || {!(call VIOC_WS_fnc_arsenalUp)}};
	uiSleep 1;
	[_unit, _token, ""] call _fnc_guard;
};

//--- "arsenalOpened": cartel con el costo de los cambios y boton Cancelar mientras estas en el Arsenal.
VIOC_WS_fnc_onOpened = {
	params [["_display", displayNull]];
	if (isNil "VIOC_WS_SESSION" || {isNil "VIOC_WS_SNAP"}) exitWith {};
	VIOC_WS_OPENED = true;
	if !(_display isEqualType displayNull) exitWith {};
	if (isNull _display) exitWith {};
	private _gw = ((safezoneW / safezoneH) min 1.2) / 40;
	private _gh = (((safezoneW / safezoneH) min 1.2) / 1.2) / 25;
	private _w = (safezoneW - 36 * _gw) max 0.5;
	private _ctrl = _display ctrlCreate ["RscStructuredText", -1];
	_ctrl ctrlSetPosition [safezoneX + 0.5 * safezoneW - 0.5 * _w, safezoneY + 0.5 * _gh, _w, 3 * _gh];
	_ctrl ctrlSetBackgroundColor [0, 0, 0, 0.65];
	_ctrl ctrlEnable false;
	_ctrl ctrlCommit 0;
	private _btn = _display ctrlCreate ["RscButton", -1];
	_btn ctrlSetPosition [safezoneX + 0.5 * safezoneW - 7 * _gw, safezoneY + 3.6 * _gh, 14 * _gw, 1.1 * _gh];
	_btn ctrlSetText "Cancelar (sin cambios)";
	_btn ctrlSetTooltip "Sale del taller sin comprar ni cambiar nada";
	_btn ctrlAddEventHandler ["ButtonClick", {
		params ["_b"];
		if (!isNil {missionNamespace getVariable "VIOC_WS_SESSION"}) then {missionNamespace setVariable ["VIOC_WS_CANCEL", true]};
		(ctrlParent _b) closeDisplay 2;
	}];
	_btn ctrlCommit 0;
	[_display, _ctrl, _btn, VIOC_WS_UNIT, VIOC_WS_SNAP, VIOC_WS_LEVEL] spawn VIOC_WS_fnc_banner;
};

VIOC_WS_fnc_banner = {
	disableSerialization;
	params ["_display", "_ctrl", "_btn", "_unit", "_snap", "_level"];
	while {!isNull _display && {!isNull _ctrl} && {!isNil "VIOC_WS_SESSION"}} do {
		if (isNull _unit || {!alive _unit}) exitWith {};
		private _e = [_snap, getUnitLoadout _unit, _level] call VIOC_WS_fnc_evaluate;
		_e params ["", "_cost", "_buys", "_pool", "_fromInv", "_rejected"];
		private _funds = call CTI_CL_FNC_GetPlayerFunds;
		if (isNil "_funds" || {!(_funds isEqualType 0)}) then {_funds = 0};
		private _txt = "<t size='1.0' color='#ffd27f'>TALLER DE ARMAS</t><t size='0.75' color='#d0d0d0'>  Arma a la izquierda; mira, boca, lateral y bipode a la derecha. Esc: aplicar y pagar (solo se guardan los accesorios).</t><br/>";
		private _col = if (_cost > _funds) then {"#F56363"} else {"#76F563"};
		_txt = _txt + format ["<t size='0.9'>Costo de los cambios: <t color='%1'>$%2</t>   Tus fondos: $%3%4</t>", _col, _cost, round _funds, ["", "   <t color='#F56363'>NO TE ALCANZA: al salir se deshace</t>"] select (_cost > _funds)];
		private _parts = [];
		if (count _buys > 0) then {_parts pushBack ("Compras: " + (_buys call VIOC_WS_fnc_names))};
		if (count _fromInv > 0) then {_parts pushBack ("De tu inventario: " + (_fromInv call VIOC_WS_fnc_names))};
		if (count _pool > 0) then {_parts pushBack ("Van a tu inventario: " + ((_pool apply {_x select 0}) call VIOC_WS_fnc_names))};
		if (count _rejected > 0) then {_parts pushBack ("No disponible en tu tienda (queda como estaba): " + (_rejected call VIOC_WS_fnc_names))};
		if (count _parts > 0) then {_txt = _txt + "<br/><t size='0.75'>" + ((_parts joinString "  |  ") call VIOC_WS_fnc_esc) + "</t>"};
		_ctrl ctrlSetStructuredText parseText _txt;
		private _p = ctrlPosition _ctrl;
		_p set [3, (ctrlTextHeight _ctrl) + 0.01];
		_ctrl ctrlSetPosition _p;
		_ctrl ctrlCommit 0;
		if (!isNull _btn) then {
			private _pb = ctrlPosition _btn;
			_pb set [1, (_p select 1) + (_p select 3) + 0.005];
			_btn ctrlSetPosition _pb;
			_btn ctrlCommit 0;
		};
		uiSleep 0.3;
	};
};

//--- "arsenalClosed": primero vuelve TODO al equipo de antes (si algo falla, no queda nada gratis); despues aplica solo
//--- los accesorios validados, cobra y avisa.
VIOC_WS_fnc_onClosed = {
	if (isNil "VIOC_WS_SESSION" || {isNil "VIOC_WS_SNAP"}) exitWith {};
	private _unit = VIOC_WS_UNIT;
	private _snap = VIOC_WS_SNAP;
	private _level = VIOC_WS_LEVEL;
	private _equip = VIOC_WS_EQUIP;
	private _cw = VIOC_WS_CURWPN;
	private _cancel = missionNamespace getVariable ["VIOC_WS_CANCEL", false];
	call VIOC_WS_fnc_cleanup;
	if (isNil "_unit" || {isNull _unit}) exitWith {};
	private _now = getUnitLoadout _unit;
	if !(_now isEqualTo _snap) then {_unit setUnitLoadout _snap};

	//--- Muerto dentro del Arsenal (solo por script: el jugador es invulnerable en el taller): el cuerpo queda con el equipo
	//--- de antes y la ropa de reaparicion ("Start with last Gear") tambien
	if (!alive _unit) exitWith {
		[_unit, _snap] call VIOC_WS_fnc_fixAttachments;
		if (_equip isEqualType [] && {count _equip > 0}) then {
			[_equip] spawn {
				params ["_equip"];
				private _t = diag_tickTime + 600;
				waitUntil {uiSleep 0.5; alive player || {diag_tickTime > _t}};
				if ((missionNamespace getVariable ["CTI_RESPAWN_PENALTY", 0]) == -1) then {missionNamespace setVariable ["cti_gear_ondeath", _equip]};
			};
		};
	};
	if (_unit != player) exitWith {[_unit, _snap] call VIOC_WS_fnc_fixAttachments};
	if (_cancel) exitWith {
		[_unit, _snap] call VIOC_WS_fnc_fixAttachments;
		[_unit, _cw] call VIOC_WS_fnc_selectWeapon;
		hint "Taller de armas: cancelado, tus armas quedaron como estaban.";
	};

	private _e = [_snap, _now, _level] call VIOC_WS_fnc_evaluate;
	_e params ["_final", "_cost", "_buys", "_pool", "_fromInv", "_rejected"];
	private _funds = call CTI_CL_FNC_GetPlayerFunds;
	if (isNil "_funds" || {!(_funds isEqualType 0)}) then {_funds = 0};

	if (_cost > 0 && {_funds < _cost}) exitWith {
		[_unit, _snap] call VIOC_WS_fnc_fixAttachments;
		[_unit, _cw] call VIOC_WS_fnc_selectWeapon;
		hint format ["Taller de armas: no te alcanza el dinero.\nLos accesorios nuevos cuestan $%1 y tienes $%2.\nTus armas quedaron como estaban.", _cost, round _funds];
	};

	if !(_final isEqualTo _snap) then {_unit setUnitLoadout _final};
	[_unit, _final] call VIOC_WS_fnc_fixAttachments;
	{_unit removeItem _x} forEach _fromInv;
	private _stored = [];
	private _lost = [];
	{
		private _c = _x select 0;
		if (_unit canAdd _c) then {_unit addItem _c; _stored pushBack _c} else {_lost pushBack _c};
	} forEach _pool;
	if (_cost > 0) then {(-_cost) call CTI_CL_FNC_ChangePlayerFunds};
	[_unit, _cw] call VIOC_WS_fnc_selectWeapon;

	if (_final isEqualTo _snap && {_rejected isEqualTo []}) exitWith {hint "Taller de armas: sin cambios."};
	private _lines = ["Taller de armas: cambios aplicados."];
	if (count _buys > 0) then {_lines pushBack ("Comprado y montado: " + (_buys call VIOC_WS_fnc_names))};
	if (count _fromInv > 0) then {_lines pushBack ("Montado desde tu inventario: " + (_fromInv call VIOC_WS_fnc_names))};
	if (count _stored > 0) then {_lines pushBack ("Guardado en tu inventario: " + (_stored call VIOC_WS_fnc_names))};
	if (count _lost > 0) then {_lines pushBack ("No cabia en tu inventario y se perdio: " + (_lost call VIOC_WS_fnc_names))};
	if (count _rejected > 0) then {_lines pushBack ("No disponible en tu tienda (quedo como estaba): " + (_rejected call VIOC_WS_fnc_names))};
	_lines pushBack format ["Costo total: $%1. Te quedan $%2.", _cost, round (_funds - _cost)];
	hint (_lines joinString "\n");
};

//--- Menu de equipo, pestana de accesorios: solo los compatibles con las armas de la unidad que editas
//--- (mira, boca, lateral, bipode; por nombre). Sin armas o si editas un vehiculo, la lista completa de siempre.
VIOC_WS_fnc_gearAccList = {
	private _all = missionNamespace getVariable ["cti_gear_list_accessories", []];
	private _target = uiNamespace getVariable ["cti_dialog_ui_gear_target", objNull];
	private _gear = uiNamespace getVariable ["cti_dialog_ui_gear_target_gear", []];
	if (!(_target isEqualType objNull) || {isNull _target} || {!(_target isKindOf "Man")} || {!(_gear isEqualType [])} || {count _gear < 1} || {!((_gear select 0) isEqualType [])}) exitWith {_all};
	private _weapons = [];
	{
		if (_x isEqualType [] && {count _x > 0} && {(_x select 0) isEqualType ""} && {(_x select 0) != ""}) then {_weapons pushBack ((_x select 0) call VIOC_WS_fnc_norm)};
	} forEach (_gear select 0);
	if (_weapons isEqualTo []) exitWith {_all};
	private _slots = [[], [], [], []];
	{
		{(_slots select _forEachIndex) append _x} forEach ([_x] call VIOC_WS_fnc_compatSlots);
	} forEach _weapons;
	private _order = [2, 0, 1, 3]; //--- mira, boca, lateral, bipode
	private _rows = [];
	{
		private _item = _x;
		private _g = -1;
		{
			if (_item in (_slots select _x)) exitWith {_g = _forEachIndex};
		} forEach _order;
		if (_g >= 0) then {_rows pushBack [_g, toLower getText (configFile >> "CfgWeapons" >> _item >> "displayName"), _item]};
	} forEach _all;
	_rows sort true;
	_rows apply {_x select 2}
};

